class Counter:
    def __init__(self, start):
        self.n = start
    def bump(self):
        self.n += 1
        return self.n
a = Counter(0)
b = Counter(100)
print(a.bump(), a.bump(), b.bump(), a.n, b.n)

class A:
    def who(self):
        return 'A'
    def hello(self):
        return 'hello ' + self.who()
class B(A):
    def who(self):
        return 'B'
class C(B):
    def __init__(self):
        self.tag = 'cee'
    def who(self):
        return 'C/' + super().who()
print(A().hello(), B().hello(), C().hello(), C().tag)
